import{_ as l,a0 as n,w as d,s as g,ao as p,I as a,x as i,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"用 git log 命令显示在特定日期的提交记录 | LCTT x X-CMD","titleTemplate":false,"description":"用 git log 命令显示在特定日期的提交记录 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 git log 命令显示在特定日期的提交记录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 git log 命令显示在特定日期的提交记录 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221024.3 ⭐️ How to display commits created on a specific day with the git log command","title":"用 git log 命令显示在特定日期的提交记录","tag":"202211","desc":""},"relativePath":"202211/20221024.3 ⭐️ How to display commits created on a specific day with the git log command.md","filePath":"[post].md"}'),r={name:"202211/20221024.3 ⭐️ How to display commits created on a specific day with the git log command.md"};function c(h,t,u,m,k,b){const e=n("Link");return d(),g("div",null,[t[15]||(t[15]=p('<h1 id="用-git-log-命令显示在特定日期的提交记录" tabindex="-1">用 git log 命令显示在特定日期的提交记录 <a class="header-anchor" href="#用-git-log-命令显示在特定日期的提交记录" aria-label="Permalink to “用 git log 命令显示在特定日期的提交记录”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/06/085449j5diiljl7dzgdr0z.jpg" alt=""></p><blockquote><p><code>git log</code> 命令是 Git 中一个很重要的查看提交记录的工具，它也是人们喜欢使用 Git 的原因之一。</p></blockquote><p><code>git log</code> 命令能够让你了解到更多关于贡献者 <ruby>提交<rt>commit</rt></ruby> 的记录。使用 <code>git log</code> 的一种方式是按日期查看提交记录 。要查看<strong>在指定日期或日期范围内</strong>创建的 Git 存储库中的提交记录，请使用带有选项 <code>--since</code> 或 <code>--until</code> 或者同时使用以上两个选项的 <code>git log</code> 命令。</p><p>首先，进入你要查看的分支（例如，<code>main</code> 分支）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout main</span></span></code></pre></div><p>接下来，你可以使用以下命令，来显示当前日期（即今天）的提交记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline --since=&quot;yesterday&quot;</span></span></code></pre></div><p>仅显示某一特定用户（例如，用户 <code>Agil</code>）在今天的提交记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline --since=&quot;yesterday&quot; --author=&quot;Agil&quot;</span></span></code></pre></div><p>还可以显示在某一日期范围内的提交记录。使用以下命令，显示在任意两个日期之间（例如，2022 年 4 月 22 日至 2022 年 4 月 24 日）的提交记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline --since=&quot;2022-04-22&quot; --until=&quot;2022-04-24&quot;</span></span></code></pre></div><p>在上面这个例子中，会输出 2022 年 4 月 22 日至 2022 年 4 月 24 日期间，不包括 2022 年 4 月 22 日的所有提交记录。如果你想要包括 2022 年 4 月 22 日的提交记录，请将命令中的 <code>2022-04-22</code> 替换为 <code>2022-04-21</code>。</p><p>运行以下命令，能够显示某一特定用户（例如，用户 <code>Agil</code>）在两个指定的日期之间的提交记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline --since=&quot;2022-04-22&quot; --until=&quot;2022-04-24&quot; --author=&quot;Agil&quot;</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Git 有很多优点，其中一个优点就是 Git 让你能够收集你项目的相关数据。<code>git log</code> 命令是一个重要的查看提交记录的工具，也是人们喜欢使用 Git 的原因之一！</p><hr>',18)),a("p",null,[t[1]||(t[1]=i("via: ",-1)),s(e,{href:"https://opensource.com/article/22/10/git-log-command"},{default:o(()=>[...t[0]||(t[0]=[i("https://opensource.com/article/22/10/git-log-command",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=i("作者：",-1)),s(e,{href:"https://opensource.com/users/agantony"},{default:o(()=>[...t[2]||(t[2]=[i("Agil Antony",-1)])]),_:1}),t[7]||(t[7]=i(" 选题：",-1)),s(e,{href:"https://github.com/lkxed"},{default:o(()=>[...t[3]||(t[3]=[i("lkxed",-1)])]),_:1}),t[8]||(t[8]=i(" 译者：",-1)),s(e,{href:"https://github.com/chai001125"},{default:o(()=>[...t[4]||(t[4]=[i("chai001125",-1)])]),_:1}),t[9]||(t[9]=i(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=i("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[i("LCTT",-1)])]),_:1}),t[13]||(t[13]=i(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[i("Linux中国",-1)])]),_:1}),t[14]||(t[14]=i(" 荣誉推出",-1))])])}const x=l(r,[["render",c]]);export{C as __pageData,x as default};
